def get_user_input():
    """Get user input for two numbers and an operator."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            operator = input("Enter the operator (+, -, *, /): ")
            num2 = float(input("Enter the second number: "))
            return num1, operator, num2
        except ValueError:
            print("Invalid input. Please enter numbers and an operator.")

def perform_operation(num1, operator, num2):
    """Perform the arithmetic operation based on the input operator."""
    if operator == "+":
        return num1 + num2
    elif operator == "-":
        return num1 - num2
    elif operator == "*":
        return num1 * num2
    elif operator == "/":
        return num1 / num2
    else:
        raise ValueError("Invalid operator. Please use +, -, *, or /.")

def main():
    """Get user input, perform the operation, and display the result."""
    num1, operator, num2 = get_user_input()
    try:
        result = perform_operation(num1, operator, num2)
        print(f"{num1} {operator} {num2} = {result}")
    except ValueError as e:
        print(e)

if __name__ == "__main__":
    main()
```
This program defines three functions: `get_user_input()` to get user input, `perform_operation()` to perform the arithmetic operation based on the input operator, and `main()` to get user input, perform the operation, and display the result. The `main()` function calls the other two functions to handle user input and perform the operation.
